/**
 * Extra "When my child is…" moments folded into the four existing groups.
 * Verse labels use official Catholic (NABRE) numbering. A few dataset numbers
 * pointed at a different verse than the note quoted; those are corrected in
 * situation-coverage.ts and checked by scripts/test-moms-bible.ts.
 * Mom's notes are a parent's wording, not Scripture.
 */
import type { NabreBookId } from "@/lib/bible/ref-map";
import type { MbColorKey } from "@/lib/moms-bible/constants";

type SituationRef = { book: NabreBookId; label: string; chapter: number; verse: number; verseEnd?: number };
type Situation = { key: string; emoji: string; title: string; refs: readonly SituationRef[]; note: string; care?: string };

const r = (book: NabreBookId, label: string, chapter: number, verse: number, verseEnd?: number): SituationRef => ({
  book,
  label,
  chapter,
  verse,
  ...(verseEnd ? { verseEnd } : {}),
});

